import fontkit from "@pdf-lib/fontkit";
import { PDFDocument, rgb, type PDFFont, type PDFPage } from "pdf-lib";
import type { SignatureMethod, SignerRole } from "@/generated/prisma/enums";

/**
 * The « Preuve de signature »: one A4 page generated by Binivol, filed with
 * the UL copy. It sums up who signed, when, how the signer was verified, and
 * the SHA-256 of each final document (docs/signature.md).
 */

export interface ProofSigner {
  role: SignerRole;
  name: string;
  quality: string | null;
  method: SignatureMethod;
  verifiedEmail: string | null;
  verifiedBy: string | null;
  signedAt: Date;
  userAgent: string | null;
  ipHash: string | null;
  typed: boolean;
}

export interface ProofDocument {
  fileName: string;
  sha256: string;
}

export interface ProofInput {
  font: Uint8Array;
  person: { ref: string; fullName: string };
  ulName: string;
  signers: ProofSigner[];
  documents: ProofDocument[];
  producedAt: Date;
}

const ROLE: Record<SignerRole, string> = {
  VOLUNTEER: "Bénévole",
  PARENT: "Représentant légal",
  CRF_REPRESENTATIVE: "Représentant de la Croix-Rouge française",
};

const METHOD: Record<SignatureMethod, string> = {
  OTP_EMAIL: "Code à 6 chiffres reçu par e-mail",
  IN_PERSON: "Identité vérifiée en présence d'un responsable",
  SESSION: "Session du responsable (connexion Google)",
};

const parisDateTime = (d: Date) =>
  new Intl.DateTimeFormat("fr-FR", {
    timeZone: "Europe/Paris",
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    timeZoneName: "short",
  }).format(d);

class Writer {
  y: number;
  constructor(
    private readonly page: PDFPage,
    private readonly font: PDFFont,
    top: number,
  ) {
    this.y = top;
  }
  line(text: string, size = 9, options: { indent?: number; color?: number; gap?: number } = {}) {
    const maxWidth = this.page.getWidth() - 100 - (options.indent ?? 0);
    const words = text.split(" ");
    let current = "";
    const lines: string[] = [];
    for (const word of words) {
      const next = current ? `${current} ${word}` : word;
      if (this.font.widthOfTextAtSize(next, size) > maxWidth && current) {
        lines.push(current);
        current = word;
      } else current = next;
    }
    if (current) lines.push(current);
    for (const l of lines) {
      const shade = options.color ?? 0.1;
      this.page.drawText(l, {
        x: 50 + (options.indent ?? 0),
        y: this.y,
        size,
        font: this.font,
        color: rgb(shade, shade, shade),
      });
      this.y -= size + 3;
    }
    this.y -= options.gap ?? 0;
  }
}

export async function renderProof(input: ProofInput): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const font = await doc.embedFont(input.font, { subset: true });
  const page = doc.addPage([595.28, 841.89]);
  const w = new Writer(page, font, 790);
  w.line("Preuve de signature électronique", 16, { gap: 4 });
  w.line(
    `${input.person.fullName} (${input.person.ref}) · ${input.ulName} · Croix-Rouge française`,
    10,
    { color: 0.3, gap: 10 },
  );
  w.line(
    "Signature électronique simple au sens du règlement eIDAS (UE n° 910/2014, article 25) : sa valeur repose sur l'ensemble des éléments ci-dessous, conservés par l'unité locale.",
    8.5,
    { color: 0.3, gap: 12 },
  );

  w.line("Documents signés (empreinte SHA-256 du fichier final)", 11, { gap: 2 });
  for (const d of input.documents) {
    w.line(d.fileName, 9, { indent: 8 });
    w.line(d.sha256, 7.5, { indent: 8, color: 0.35, gap: 2 });
  }
  w.y -= 8;

  w.line("Signataires", 11, { gap: 2 });
  for (const s of input.signers) {
    w.line(`${ROLE[s.role]} : ${s.name}${s.quality ? `, ${s.quality}` : ""}`, 9.5, { indent: 8 });
    w.line(`Signé le ${parisDateTime(s.signedAt)} (horodatage du serveur)`, 8.5, {
      indent: 16,
    });
    w.line(
      `Vérification : ${METHOD[s.method]}${s.verifiedEmail ? `, ${s.verifiedEmail}` : ""}${s.verifiedBy ? `, par ${s.verifiedBy}` : ""}`,
      8.5,
      { indent: 16 },
    );
    w.line(
      `Tracé : ${s.typed ? "nom saisi (police manuscrite)" : "tracé au doigt, stylet ou souris"}`,
      8.5,
      {
        indent: 16,
      },
    );
    if (s.userAgent)
      w.line(`Navigateur : ${s.userAgent.slice(0, 160)}`, 7.5, { indent: 16, color: 0.35 });
    if (s.ipHash)
      w.line(`Empreinte de l'adresse IP : ${s.ipHash}`, 7.5, { indent: 16, color: 0.35 });
    w.y -= 4;
  }
  w.y -= 6;
  w.line(`Preuve produite par Binivol le ${parisDateTime(input.producedAt)}.`, 8, { color: 0.35 });
  w.line(
    "L'adresse IP n'est pas conservée : seule son empreinte (HMAC-SHA256) l'est. Les fichiers signés sont aplatis (aucun champ modifiable) ; toute modification change leur empreinte.",
    8,
    { color: 0.35 },
  );

  doc.setTitle("Preuve de signature");
  doc.setProducer("Binivol");
  doc.setCreator("Binivol");
  doc.setCreationDate(input.producedAt);
  doc.setModificationDate(input.producedAt);
  return doc.save({ useObjectStreams: false });
}
